const vars = runtimeScene.getVariables();
const timeManager = runtimeScene.getTimeManager();
const dt = timeManager ? Math.max(0, timeManager.getElapsedTime() / 1000) : 1 / 60;
const players = runtimeScene.getObjects('Player');
const player = players.length ? players[0] : null;
const phase = vars.get('RoundPhase').getAsString();
const testMode = runtimeScene.__iceWolfV065TestMode === true;
const playerActive = !!player && player.getVariables().get('State').getAsString() === 'Active';
const playing = !!player && (phase === 'Active' || testMode) && !vars.get('GameOver').getAsBoolean() && playerActive;
const insidePad = (pad, cx, cy, margin) => {
  const left = pad.getX() - margin;
  const top = pad.getY() - margin;
  const right = left + pad.getWidth() + margin * 2;
  const bottom = top + pad.getHeight() + margin * 2;
  return cx >= left && cx <= right && cy >= top && cy <= bottom;
};
const showFeedback = (text, seconds) => {
  for (const obj of runtimeScene.getObjects('ActionFeedbackText')) {
    if (typeof obj.setString === 'function') obj.setString(text);
    if (typeof obj.hide === 'function') obj.hide(false);
  }
  vars.get('FeedbackLeft').setNumber(seconds);
};
let warpCooldown = Math.max(0, vars.get('WarpCooldownLeft').getAsNumber() - dt);
let boostLeft = Math.max(0, vars.get('SpeedBoostLeft').getAsNumber() - dt);
let onSpeedPad = false;
if (playing) {
  const cx = player.getCenterXInScene();
  const cy = player.getCenterYInScene();
  for (const pad of runtimeScene.getObjects('SpeedPad')) {
    if (insidePad(pad, cx, cy, 2)) onSpeedPad = true;
  }
  if (onSpeedPad && runtimeScene.__iceWolfV068OnSpeedPad !== true) {
    boostLeft = vars.get('SpeedBoostDuration').getAsNumber();
    vars.get('SpeedPadTriggers').setNumber(vars.get('SpeedPadTriggers').getAsNumber() + 1);
    showFeedback('⚡ スピードアップ！', 1.3);
  }
  if (warpCooldown <= 0) {
    const warps = runtimeScene.getObjects('WarpPad');
    if (warps.length >= 2) {
      let source = null;
      for (const pad of warps) {
        if (insidePad(pad, cx, cy, 0)) {
          source = pad;
          break;
        }
      }
      if (source) {
        let destination = null;
        for (const pad of warps) {
          if (pad !== source) {
            destination = pad;
            break;
          }
        }
        if (destination) {
          player.setX(destination.getX() + destination.getWidth() / 2 - player.getWidth() / 2);
          player.setY(destination.getY() + destination.getHeight() / 2 - player.getHeight() / 2);
          if (typeof player.setZ === 'function') player.setZ(0);
          warpCooldown = vars.get('WarpCooldownDuration').getAsNumber();
          vars.get('WarpCount').setNumber(vars.get('WarpCount').getAsNumber() + 1);
          showFeedback('🌀 ワープ！', 1.1);
        }
      }
    }
  }
} else {
  warpCooldown = 0;
  boostLeft = 0;
}

  // v1.0.0 Build 10: allow all Active Actors (Human AI & Wolf AI) to use WarpPad & SpeedPad
  const warpsAll = runtimeScene.getObjects('WarpPad');
  const speedPadsAll = runtimeScene.getObjects('SpeedPad');
  for (const actor of runtimeScene.getObjects('Actor')) {
    const av = actor.getVariables();
    if (av.get('State').getAsString() !== 'Active') {
      actor.__iceWolfV068WarpCooldown = 0;
      actor.__iceWolfV068SpeedBoostLeft = 0;
      continue;
    }
    actor.__iceWolfV068WarpCooldown = Math.max(0, (Number.isFinite(actor.__iceWolfV068WarpCooldown) ? actor.__iceWolfV068WarpCooldown : 0) - dt);
    actor.__iceWolfV068SpeedBoostLeft = Math.max(0, (Number.isFinite(actor.__iceWolfV068SpeedBoostLeft) ? actor.__iceWolfV068SpeedBoostLeft : 0) - dt);
    const acx = actor.getCenterXInScene();
    const acy = actor.getCenterYInScene();
    for (const spad of speedPadsAll) {
      if (insidePad(spad, acx, acy, 2)) {
        actor.__iceWolfV068SpeedBoostLeft = vars.get('SpeedBoostDuration').getAsNumber();
        break;
      }
    }
    if (actor.__iceWolfV068WarpCooldown <= 0 && warpsAll.length >= 2) {
      let src = null;
      for (const wpad of warpsAll) {
        if (insidePad(wpad, acx, acy, 0)) { src = wpad; break; }
      }
      if (src) {
        let dst = null;
        for (const wpad of warpsAll) {
          if (wpad !== src) { dst = wpad; break; }
        }
        if (dst) {
          actor.setX(dst.getX() + dst.getWidth() / 2 - actor.getWidth() / 2);
          actor.setY(dst.getY() + dst.getHeight() / 2 - actor.getHeight() / 2);
          if (typeof actor.setZ === 'function') actor.setZ(0);
          actor.__iceWolfV068WarpCooldown = 4.0;
          actor.__iceWolfV074Path = null;
          actor.__iceWolfV074Still = 0;
        }
      }
    }
  }

runtimeScene.__iceWolfV068OnSpeedPad = playing ? onSpeedPad : false;
vars.get('SpeedBoostLeft').setNumber(boostLeft);
vars.get('WarpCooldownLeft').setNumber(warpCooldown);
vars.get('OnSpeedPad').setBoolean(playing && onSpeedPad);
vars.get('SpeedFactor').setNumber(boostLeft > 0 ? vars.get('SpeedBoostFactor').getAsNumber() : 1);

/* ICE WOLF v0.7.4 — how the CPUs walk around the FROST LAB.
 *
 * What went wrong up to v0.7.3
 *   A CPU was moved by pushing it straight at its goal and letting
 *   `SeparateFromObjects` slide it along the wall. FROST LAB has four rooms whose
 *   only opening is a 60px doorway on the south side, so "straight at the goal"
 *   runs into a wall most of the time, and the slide cancelled the walk. The only
 *   recovery was the blocked detour: the Wolf flipped its detour side on every
 *   re-trigger (left, right, left on the same corner — the "the wolf's movement is
 *   buggy" that was reported) and a Human kept the one side its quadrant gave it,
 *   which could point into the wall for the rest of the round (a character that
 *   never moves — the one トモアキさん saw standing still).
 *
 * What this block does instead
 *   1. A 16px navigation grid per floor is built once from the Wall objects
 *      (memory: 88×88 cells per floor, no per-frame work).
 *   2. `__iceWolfV074PathDir(obj, x, y)` runs a breadth-first search from the goal
 *      cell and follows the resulting cells, skipping ahead while the line is
 *      clear. A CPU therefore walks to the doorway, into the room, around the
 *      pillars and back out — the map's real shape, not a greedy guess. The search
 *      is rebuilt at most every 0.5s per CPU, and never while the goal is in sight.
 *   3. `__iceWolfV074Steer(obj, vx, vy, speed, goalX, goalY)` wraps it: the path
 *      direction when the goal is not in sight, then a 16-way wall fan with a side
 *      that is held (not re-decided every frame), a wall-normal step for a CPU that
 *      is squeezed into the padding, and a hard unstick after 1.0s without real
 *      movement.
 *
 * Everything here is read-only for the game state: the speeds, the pads, the
 * warps, the hitbox and the player's own controls are untouched.
 */
const vars = runtimeScene.getVariables();
const elapsed = gdjs.evtTools.runtimeScene.getElapsedTimeInSeconds(runtimeScene);
const dt = Math.max(0, Math.min(0.1, Number.isFinite(elapsed) ? elapsed : 0.016));
const WALL_MARGIN = 7;          // just under the 8.5px body half: a CPU standing
                                // flush against a wall is not "inside" the padding,
                                // and one that is squeezed in walks out along the normal
const LOOK_AHEAD = 54;          // ~0.35s at a jog: enough to clear a 32px wall
const FAN_STEP = Math.PI / 8;   // 22.5° × 16 directions
const FAN_STEPS = 7;            // up to 157.5° off the wanted direction
const UNSTICK_AFTER = 1.0;
const UNSTICK_FOR = 0.7;
const FLOOR_GAP_X = 792;
const CELL = 16;
const GRID_MARGIN = 0;          // the grid only needs the cell centre to be a body
                                // half-width from the wall, so it can use the 32px
                                // slots the floor plan has; the ray test above stays
                                // stricter (WALL_MARGIN)
const PATH_REFRESH = 0.5;       // seconds between two searches for one CPU
const PATH_GOAL_SLACK = 24;     // px the goal may drift before a new search

let rects = runtimeScene.__iceWolfV074Rects;
if (!rects) {
  rects = [];
  runtimeScene.__iceWolfV074Rects = rects;
}
rects.length = 0;
for (const wall of runtimeScene.getObjects('Wall')) {
  rects.push(
    wall.getX() - WALL_MARGIN,
    wall.getY() - WALL_MARGIN,
    wall.getX() + wall.getWidth() + WALL_MARGIN,
    wall.getY() + wall.getHeight() + WALL_MARGIN
  );
}

/* Slab test: does (x,y)-(ex,ey) touch the padded rectangle? */
const segmentHits = (x, y, ex, ey, left, top, right, bottom) => {
  const dx = ex - x;
  const dy = ey - y;
  let t0 = 0;
  let t1 = 1;
  if (dx === 0) {
    if (x < left || x > right) return false;
  } else {
    let ta = (left - x) / dx;
    let tb = (right - x) / dx;
    if (ta > tb) { const swap = ta; ta = tb; tb = swap; }
    if (ta > t0) t0 = ta;
    if (tb < t1) t1 = tb;
    if (t0 > t1) return false;
  }
  if (dy === 0) {
    if (y < top || y > bottom) return false;
  } else {
    let ta = (top - y) / dy;
    let tb = (bottom - y) / dy;
    if (ta > tb) { const swap = ta; ta = tb; tb = swap; }
    if (ta > t0) t0 = ta;
    if (tb < t1) t1 = tb;
    if (t0 > t1) return false;
  }
  return t0 <= t1;
};

const clearPath = (x, y, dirX, dirY, distance) => {
  const ex = x + dirX * distance;
  const ey = y + dirY * distance;
  const xMin = x > FLOOR_GAP_X ? 900.5 : -699.5;
  const xMax = x > FLOOR_GAP_X ? 2300.5 : 700.5;
  if (ex < xMin || ex > xMax || ey < -699.5 || ey > 700.5) return false;
  for (let i = 0; i < rects.length; i += 4) {
    if (segmentHits(x, y, ex, ey, rects[i], rects[i + 1], rects[i + 2], rects[i + 3])) return false;
  }
  return true;
};

/* ---------------------------------------------------------------- the grid
 * One grid per floor. A cell is walkable when the 16px square, grown by the
 * margin the body needs, touches no wall, and the cell centre stays inside the
 * floor's own playable band (the 1F/2F clamp the AI already uses).
 */
const FLOOR_BOXES = {
  '1F': { x0: -704, y0: -704, x1: 704, y1: 704, minX: -700, maxX: 700 },
  '2F': { x0: 848, y0: -704, x1: 2304, y1: 704, minX: 900, maxX: 2300 }
};
const DI = [1, -1, 0, 0, 1, 1, -1, -1];
const DJ = [0, 0, 1, -1, 1, -1, 1, -1];

const buildGrid = (box, walls) => {
  const w = Math.round((box.x1 - box.x0) / CELL);
  const h = Math.round((box.y1 - box.y0) / CELL);
  const walk = new Uint8Array(w * h);
  walk.fill(1);
  for (let j = 0; j < h; j += 1) {
    const cy = box.y0 + (j + 0.5) * CELL;
    for (let i = 0; i < w; i += 1) {
      const cx = box.x0 + (i + 0.5) * CELL;
      if (cx < box.minX || cx > box.maxX || cy < -699 || cy > 700) walk[j * w + i] = 0;
    }
  }
  for (const wall of walls) {
    const left = wall.getX() - GRID_MARGIN;
    const top = wall.getY() - GRID_MARGIN;
    const right = wall.getX() + wall.getWidth() + GRID_MARGIN;
    const bottom = wall.getY() + wall.getHeight() + GRID_MARGIN;
    const i0 = Math.max(0, Math.floor((left - box.x0) / CELL));
    const i1 = Math.min(w - 1, Math.ceil((right - box.x0) / CELL) - 1);
    const j0 = Math.max(0, Math.floor((top - box.y0) / CELL));
    const j1 = Math.min(h - 1, Math.ceil((bottom - box.y0) / CELL) - 1);
    for (let j = j0; j <= j1; j += 1) {
      for (let i = i0; i <= i1; i += 1) walk[j * w + i] = 0;
    }
  }
  return {
    box,
    w,
    h,
    walk,
    dist: new Int32Array(w * h),
    parent: new Int32Array(w * h),
    seen: new Int32Array(w * h),
    queue: new Int32Array(w * h),
    gen: 0
  };
};

const gridFor = (cx) => {
  if (!runtimeScene.__iceWolfV074Grid) {
    const all = runtimeScene.getObjects('Wall');
    const first = all.filter((wall) => wall.getX() < 840);
    const second = all.filter((wall) => wall.getX() >= 840);
    runtimeScene.__iceWolfV074Grid = {
      '1F': buildGrid(FLOOR_BOXES['1F'], first),
      '2F': buildGrid(FLOOR_BOXES['2F'], second)
    };
  }
  const grids = runtimeScene.__iceWolfV074Grid;
  return cx > FLOOR_GAP_X ? grids['2F'] : grids['1F'];
};

const cellOf = (grid, x, y) => {
  const i = Math.floor((x - grid.box.x0) / CELL);
  const j = Math.floor((y - grid.box.y0) / CELL);
  if (i < 0 || j < 0 || i >= grid.w || j >= grid.h) return -1;
  return j * grid.w + i;
};

const centerXOf = (grid, cell) => grid.box.x0 + ((cell % grid.w) + 0.5) * CELL;
const centerYOf = (grid, cell) => grid.box.y0 + (Math.floor(cell / grid.w) + 0.5) * CELL;

/* The given cell, or the closest walkable one around it (a switch can sit right
 * against a wall, and a CPU can be standing in the padded band). */
const nearestWalkable = (grid, cell, radius, fromX, fromY) => {
  if (cell < 0) return -1;
  if (grid.walk[cell]) return cell;
  const ci = cell % grid.w;
  const cj = (cell - ci) / grid.w;
  let best = -1;
  let bestDistance = Infinity;
  let bestSeen = -1;
  for (let ring = 1; ring <= radius; ring += 1) {
    for (let dj = -ring; dj <= ring; dj += 1) {
      for (let di = -ring; di <= ring; di += 1) {
        if (Math.abs(di) !== ring && Math.abs(dj) !== ring) continue;
        const ni = ci + di;
        const nj = cj + dj;
        if (ni < 0 || nj < 0 || ni >= grid.w || nj >= grid.h) continue;
        const candidate = nj * grid.w + ni;
        if (!grid.walk[candidate]) continue;
        const distance = di * di + dj * dj;
        if (distance < bestDistance) {
          bestDistance = distance;
          best = candidate;
        }
        /* A cell on the other side of the same wall is no use as a start: prefer
         * one the CPU can walk to in a straight line. */
        if (bestSeen < 0 && Number.isFinite(fromX) && Number.isFinite(fromY)) {
          const wx = centerXOf(grid, candidate);
          const wy = centerYOf(grid, candidate);
          const length = Math.hypot(wx - fromX, wy - fromY);
          if (length < 1 || clearPath(fromX, fromY, (wx - fromX) / length, (wy - fromY) / length, length)) {
            bestSeen = candidate;
          }
        }
      }
    }
    if (bestSeen >= 0) return bestSeen;
    if (best >= 0) return best;
  }
  return -1;
};

/* Breadth-first search from the goal, stopping when the CPU's own cell is
 * reached. parent[] then walks from the CPU to the goal. */
const searchFrom = (grid, goalCell, startCell) => {
  grid.gen += 1;
  const gen = grid.gen;
  const { w, h, walk, dist, parent, seen, queue } = grid;
  seen[goalCell] = gen;
  dist[goalCell] = 0;
  parent[goalCell] = -1;
  let head = 0;
  let tail = 0;
  queue[tail++] = goalCell;
  while (head < tail) {
    const cell = queue[head++];
    if (cell === startCell) return true;
    const ci = cell % w;
    const cj = (cell - ci) / w;
    const nextDist = dist[cell] + 1;
    for (let k = 0; k < 8; k += 1) {
      const ni = ci + DI[k];
      const nj = cj + DJ[k];
      if (ni < 0 || nj < 0 || ni >= w || nj >= h) continue;
      const neighbour = nj * w + ni;
      if (!walk[neighbour] || seen[neighbour] === gen) continue;
      if (k >= 4 && (!walk[cj * w + ni] || !walk[nj * w + ci])) continue;
      seen[neighbour] = gen;
      dist[neighbour] = nextDist;
      parent[neighbour] = cell;
      queue[tail++] = neighbour;
    }
  }
  return seen[startCell] === gen;
};

const rebuildPath = (obj, grid, cx, cy, goalX, goalY) => {
  const start = nearestWalkable(grid, cellOf(grid, cx, cy), 3, cx, cy);
  const goal = nearestWalkable(grid, cellOf(grid, goalX, goalY), 3, NaN, NaN);
  obj.__iceWolfV074GoalX = goalX;
  obj.__iceWolfV074GoalY = goalY;
  obj.__iceWolfV074PathAt = 0;
  obj.__iceWolfV074PathTime = elapsed;
  obj.__iceWolfV074Path = null;
  if (start < 0 || goal < 0) return;
  vars.get('AiNavSearchCount').setNumber(vars.get('AiNavSearchCount').getAsNumber() + 1);
  if (!searchFrom(grid, goal, start)) return;
  const points = [];
  let cell = start;
  let guard = 0;
  while (cell >= 0 && guard < grid.w * grid.h) {
    points.push(centerXOf(grid, cell), centerYOf(grid, cell));
    cell = grid.parent[cell];
    guard += 1;
  }
  obj.__iceWolfV074Path = points;
  vars.get('AiNavPathCount').setNumber(vars.get('AiNavPathCount').getAsNumber() + 1);
};

const pathDirection = (obj, cx, cy, goalX, goalY) => {
  const grid = gridFor(cx);
  const path = obj.__iceWolfV074Path;
  const goalMoved = !Number.isFinite(obj.__iceWolfV074GoalX)
    || Math.abs(goalX - obj.__iceWolfV074GoalX) > PATH_GOAL_SLACK
    || Math.abs(goalY - obj.__iceWolfV074GoalY) > PATH_GOAL_SLACK;
  const stale = !Number.isFinite(obj.__iceWolfV074PathTime)
    || elapsed - obj.__iceWolfV074PathTime > PATH_REFRESH;
  if (!path || goalMoved || stale) rebuildPath(obj, grid, cx, cy, goalX, goalY);
  const points = obj.__iceWolfV074Path;
  if (!points || !points.length) return null;
  let at = obj.__iceWolfV074PathAt || 0;
  while (at < points.length / 2 && Math.hypot(points[at * 2] - cx, points[at * 2 + 1] - cy) < 14) at += 1;
  /* Skip ahead along the path while the line stays clear: no grid zig-zag. */
  const last = Math.min(points.length / 2 - 1, at + 12);
  let pick = at;
  for (let k = last; k > at; k -= 1) {
    const wx = points[k * 2];
    const wy = points[k * 2 + 1];
    const distance = Math.hypot(wx - cx, wy - cy);
    if (distance < 1) continue;
    if (clearPath(cx, cy, (wx - cx) / distance, (wy - cy) / distance, distance)) {
      pick = k;
      break;
    }
  }
  obj.__iceWolfV074PathAt = pick;
  const tx = points[pick * 2] - cx;
  const ty = points[pick * 2 + 1] - cy;
  const length = Math.hypot(tx, ty);
  if (!(length > 0.5)) return null;
  return { x: tx / length, y: ty / length };
};

/* A CPU squeezed into the padding (a corner, or the frame a wall was separated
 * from) sees every direction as blocked, because a ray that starts inside a
 * rectangle always touches it. That is the one case where the wall normal is the
 * answer: walk straight out first. */
const escapeStep = (cx, cy) => {
  let nx = 0;
  let ny = 0;
  let inside = 0;
  for (let i = 0; i < rects.length; i += 4) {
    const left = rects[i];
    const top = rects[i + 1];
    const right = rects[i + 2];
    const bottom = rects[i + 3];
    if (cx <= left || cx >= right || cy <= top || cy >= bottom) continue;
    const toLeft = cx - left;
    const toRight = right - cx;
    const toTop = cy - top;
    const toBottom = bottom - cy;
    const shortest = Math.min(toLeft, toRight, toTop, toBottom);
    if (shortest === toLeft) nx -= 1;
    else if (shortest === toRight) nx += 1;
    else if (shortest === toTop) ny -= 1;
    else ny += 1;
    inside += 1;
  }
  if (!inside) return null;
  const length = Math.hypot(nx, ny);
  if (!(length > 0)) return null;
  return { x: nx / length, y: ny / length };
};

/* The smallest turn towards `side` (+1 / -1) that is clear, or 0 if that whole
 * side of the fan is closed. */
const firstClearStep = (x, y, base, side) => {
  for (let step = 1; step <= FAN_STEPS; step += 1) {
    const angle = base + side * step * FAN_STEP;
    if (clearPath(x, y, Math.cos(angle), Math.sin(angle), LOOK_AHEAD)) return step;
  }
  return 0;
};

const steer = (obj, wantX, wantY, speed, goalX, goalY) => {
  const cx = obj.getCenterXInScene();
  const cy = obj.getCenterYInScene();
  const lastX = obj.__iceWolfV074PrevX;
  const lastY = obj.__iceWolfV074PrevY;
  const moved = (Number.isFinite(lastX) && Number.isFinite(lastY))
    ? Math.hypot(cx - lastX, cy - lastY)
    : 9999;
  obj.__iceWolfV074PrevX = cx;
  obj.__iceWolfV074PrevY = cy;

  const wanted = Math.hypot(wantX, wantY);
  if (!(wanted > 0.001) || !(speed > 1)) {
    obj.__iceWolfV074Still = 0;
    obj.__iceWolfV074UnstickLeft = 0;
    return { x: 0, y: 0 };
  }
  obj.__iceWolfV074Calls = (Number.isFinite(obj.__iceWolfV074Calls) ? obj.__iceWolfV074Calls : 0) + 1;

  /* A stair ride or a warp lands far away, so it never counts as standing still. */
  if (!Number.isFinite(obj.__iceWolfV074WinX) || !Number.isFinite(obj.__iceWolfV074WinY) || moved > 80) {
    obj.__iceWolfV074WinX = cx;
    obj.__iceWolfV074WinY = cy;
    obj.__iceWolfV074WinT = 0;
  } else {
    obj.__iceWolfV074WinT = (obj.__iceWolfV074WinT || 0) + dt;
    if (obj.__iceWolfV074WinT >= 0.6) {
      const netMoved = Math.hypot(cx - obj.__iceWolfV074WinX, cy - obj.__iceWolfV074WinY);
      if (netMoved < 14) {
        obj.__iceWolfV074Still = UNSTICK_AFTER;
      }
      obj.__iceWolfV074WinX = cx;
      obj.__iceWolfV074WinY = cy;
      obj.__iceWolfV074WinT = 0;
    }
  }
  if (moved < 0.2) {
    obj.__iceWolfV074Still = (Number.isFinite(obj.__iceWolfV074Still) ? obj.__iceWolfV074Still : 0) + dt;
  } else if (obj.__iceWolfV074Still < UNSTICK_AFTER) {
    obj.__iceWolfV074Still = 0;
  }

  let unstickLeft = Number.isFinite(obj.__iceWolfV074UnstickLeft) ? obj.__iceWolfV074UnstickLeft : 0;
  if (unstickLeft <= 0 && obj.__iceWolfV074Still >= UNSTICK_AFTER) {
    let chosenX = 0;
    let chosenY = 0;
    let found = false;
    const baseAngle = Math.random() * Math.PI * 2;
    const reaches = [LOOK_AHEAD, LOOK_AHEAD / 2, 14];
    for (let attempt = 0; attempt < reaches.length && !found; attempt += 1) {
      for (let k = 0; k < 16 && !found; k += 1) {
        const angle = baseAngle + k * FAN_STEP;
        if (clearPath(cx, cy, Math.cos(angle), Math.sin(angle), reaches[attempt])) {
          chosenX = Math.cos(angle);
          chosenY = Math.sin(angle);
          found = true;
        }
      }
    }
    obj.__iceWolfV074Still = 0;
    obj.__iceWolfV074Path = null;
    if (found) {
      obj.__iceWolfV074UnstickX = chosenX;
      obj.__iceWolfV074UnstickY = chosenY;
      obj.__iceWolfV074UnstickLeft = UNSTICK_FOR;
      unstickLeft = UNSTICK_FOR;
      vars.get('AiSteerUnstickCount').setNumber(vars.get('AiSteerUnstickCount').getAsNumber() + 1);
    }
  }
  if (unstickLeft > 0) {
