/* v0.7.2 — the AI side of the stairs.
 * The pads and the warp are exactly v0.7.0's, shared with the player (2.4s there, so
 * the feel does not change). Every CPU rider gets its own 4.0-5.0s cooldown, drawn per
 * ride so seven characters never share one beat; it lands 76px inside the floor so it
 * no longer stands on its destination pad; and it starts a floor lock (Wolf 7.0s,
 * Human 3.0s) that keeps it hunting or working the floor it arrived on before it may
 * cross again. The cooldown, the step-off and the lock together make the ping-pong
 * impossible without touching the ride itself. */
const clearOfWalls = (rider, x, y) => {
  const right = x + rider.getWidth();
  const bottom = y + rider.getHeight();
  for (const wall of objects('Wall')) {
    if (right <= wall.getX() || wall.getX() + wall.getWidth() <= x) continue;
    if (bottom <= wall.getY() || wall.getY() + wall.getHeight() <= y) continue;
    return false;
  }
  return true;
};
const stepOffPad = (rider, destination, toFloor) => {
  const room = toFloor === '2F' ? [X_MIN_2F, X_MAX_2F] : [X_MIN_1F, X_MAX_1F];
  const roomCenterX = (room[0] + room[1]) / 2;
  const padCenterX = destination.getX() + destination.getWidth() / 2;
  const towardCenter = padCenterX >= roomCenterX ? -AI_STAIR_STEP_OUT : AI_STAIR_STEP_OUT;
  const candidates = [[towardCenter, 0], [-towardCenter, 0], [0, AI_STAIR_STEP_OUT], [0, -AI_STAIR_STEP_OUT]];
  for (const candidate of candidates) {
    const nx = Math.max(room[0], Math.min(room[1], rider.getX() + candidate[0]));
    const ny = Math.max(Y_MIN, Math.min(Y_MAX, rider.getY() + candidate[1]));
    if (clearOfWalls(rider, nx, ny)) {
      rider.setX(nx);
      rider.setY(ny);
      return;
    }
  }
};
const rideStairs = (rider, isPlayer) => {
  if (!rider) return false;
  if (isPlayer) {
    if (stairCooldown > 0) return false;
  } else {
    const left = Number.isFinite(rider.__iceWolfV070StairCooldown) ? rider.__iceWolfV070StairCooldown : 0;
    rider.__iceWolfV070StairCooldown = Math.max(0, left - dt);
    if (rider.__iceWolfV070StairCooldown > 0) return false;
  }
  for (let i = 0; i < stairPads.length; i += 1) {
    if (!insideRect(rider, rectOf(stairPads[i], 0), 0)) continue;
    // stairs are laid out as [1F-A, 1F-B, 2F-A, 2F-B]: 0<->2 and 1<->3
    const destinationIndex = i < 2 ? i + 2 : i - 2;
    const destination = stairPads[destinationIndex];
    if (!destination) return false;
    const fromFloor = floorNameFor(rider.getCenterXInScene());
    rider.setX(destination.getX() + destination.getWidth() / 2 - rider.getWidth() / 2);
    rider.setY(destination.getY() + destination.getHeight() / 2 - rider.getHeight() / 2);
    if (typeof rider.setZ === 'function') rider.setZ(0);
    if (isPlayer) {
      stairCooldown = STAIR_COOLDOWN;
    } else {
      rider.__iceWolfV070StairCooldown = AI_STAIR_COOLDOWN_MIN + Math.random() * (AI_STAIR_COOLDOWN_MAX - AI_STAIR_COOLDOWN_MIN);
    }
