      rider.__iceWolfV072LastFloor = toFloor;
      rider.__iceWolfV072FloorLockLeft = isWolfRider ? AI_WOLF_FLOOR_LOCK : AI_HUMAN_FLOOR_LOCK;
      rider.__iceWolfV072CrossDelay = 0.5 + Math.random() * 1.3;
      if (isWolfRider) rider.__iceWolfV072PatrolLeft = 4.0;
