      vars.get('AiStairLastRider').setString(isWolfRider ? 'Wolf' : 'Human');
      vars.get('AiStairLastFrom').setString(fromFloor);
      vars.get('AiStairLastTo').setString(toFloor);
    }
    return true;
  }
  return false;
};
