await harness.goToScene('FROST LAB');
harness.setSceneVariable('LanguageCommand', 'ja');
harness.setSceneVariable('RoundCommand', 'TestStartWolf');
await harness.stepFrames(3);
await harness.stepFrames(12);
const players = harness.getObjects('Player');
harness.assert(players.length === 1, 'Player exists x1, got '+players.length);
const p = players[0];
harness.assert(p.width <= 25 && p.height <= 25, `Player small: w=${p.width} h=${p.height} (expect <=25)`);
harness.assert((p.depth ?? p.height) <= 45, `Player low height: d=${p.depth} (expect <=45)`);
// virtual joystick replaces the old 8-button dpad
const sticks = harness.getObjects('MoveStick');
harness.assert(sticks.length === 0, 'Old MoveStick gone');
for (const n of ['Dpad_N','Dpad_S','Dpad_E','Dpad_W','Dpad_NW','Dpad_NE','Dpad_SW','Dpad_SE']) {
  harness.assert(harness.getObjects(n).length === 0, n+' not instantiated');
}
harness.assert(harness.getSceneVariable('VirtualJoystickReady')?.value === true, 'Virtual joystick initialized');
// camera follows: record camera before/after move
const cam0 = harness.getCameraState('');
const x0 = p.centerX, y0 = p.centerY;
harness.setKeyPressed('Up', true);
await harness.stepFrames(20);
harness.setKeyPressed('Up', false);
const p1 = harness.getObjects('Player')[0];
const cam1 = harness.getCameraState('');
harness.assert(p1.centerY < y0 - 30, `Up moves screen-up: y ${y0} -> ${p1.centerY}`);
harness.assert(Math.abs(cam1.x - cam0.x) + Math.abs(cam1.y - cam0.y) > 5, `Camera follows player (moved ${Math.abs(cam1.x-cam0.x)+Math.abs(cam1.y-cam0.y)})`);
// down/left/right
async function moveCheck(key, fn, label) {
  const a = harness.getObjects('Player')[0];
  harness.setKeyPressed(key, true);
  await harness.stepFrames(20);
  harness.setKeyPressed(key, false);
  const b = harness.getObjects('Player')[0];
  harness.assert(fn(a,b), label+` a=(${a.centerX},${a.centerY}) b=(${b.centerX},${b.centerY})`);
}
await moveCheck('Down', (a,b)=> b.centerY > a.centerY+30, 'Down moves down');
await moveCheck('Left', (a,b)=> b.centerX < a.centerX-30, 'Left moves left');
await moveCheck('Right', (a,b)=> b.centerX > a.centerX+30, 'Right moves right');
// diagonal + normalize: speed diagonal ~= cardinal
const pa = harness.getObjects('Player')[0];
harness.setKeyPressed('Up', true);
await harness.stepFrames(20);
harness.setKeyPressed('Up', false);
const pb = harness.getObjects('Player')[0];
const cardDist = Math.hypot(pb.centerX-pa.centerX, pb.centerY-pa.centerY);
const pc = harness.getObjects('Player')[0];
harness.setKeyPressed('Up', true); harness.setKeyPressed('Right', true);
await harness.stepFrames(20);
harness.setKeyPressed('Up', false); harness.setKeyPressed('Right', false);
const pd = harness.getObjects('Player')[0];
const diagDist = Math.hypot(pd.centerX-pc.centerX, pd.centerY-pc.centerY);
harness.assert(diagDist > 20, `Diagonal moves: dist=${diagDist}`);
harness.assert(Math.abs(diagDist - cardDist) / cardDist < 0.25, `Diagonal normalized: card=${cardDist} diag=${diagDist}`);
// no fall: z stable
const z = harness.getObjects('Player')[0].z ?? 0;
harness.assert(z > -50 && z < 100, `Player not fallen: z=${z}`);
// camera distance stable: zoom unchanged across movement
harness.assert(Math.abs(cam1.zoom - harness.getCameraState('').zoom) < 0.01, 'Camera zoom stable');

await harness.goToScene('FROST LAB');
harness.setSceneVariable('LanguageCommand', 'ja');
harness.setSceneVariable('RoundCommand', 'TestStartWolf');
await harness.stepFrames(3);
await harness.stepFrames(30);
let p = harness.getObjects('Player')[0];
harness.setObjectPosition(p.id, -600, 350);
await harness.stepFrames(5);
p = harness.getObjects('Player')[0];
harness.assert(true, `teleported to (${p.centerX.toFixed(1)},${p.centerY.toFixed(1)})`);
harness.setKeyPressed('Left', true);
await harness.stepFrames(150);
harness.setKeyPressed('Left', false);
p = harness.getObjects('Player')[0];
harness.assert(p.centerX > -720, `Blocked by west wall: x=${p.centerX.toFixed(1)} (wall face -720)`);
harness.assert((p.z ?? 0) > -50, `No fall: z=${p.z}`);

await harness.goToScene('FROST LAB');
harness.setSceneVariable('LanguageCommand', 'ja');
harness.setSceneVariable('RoundCommand', 'TestStartWolf');
await harness.stepFrames(3);
await harness.stepFrames(30);
async function tp(x, y) {
  const p = harness.getObjects('Player')[0];
  harness.setObjectPosition(p.id, x, y);
  await harness.stepFrames(5);
  return harness.getObjects('Player')[0];
}
async function hold(keys, frames) {
  for (const k of keys) harness.setKeyPressed(k, true);
  await harness.stepFrames(frames);
  for (const k of keys) harness.setKeyPressed(k, false);
  return harness.getObjects('Player')[0];
}
// S1: cannot exit west outer wall
await tp(-600, 350);
let p = await hold(['Left'], 200);
harness.assert(p.centerX > -720, `S1 west wall holds: x=${p.centerX.toFixed(1)}`);
// S1b: cannot exit north outer wall
await tp(0, -600);
p = await hold(['Up'], 200);
harness.assert(p.centerY > -720, `S1 north wall holds: y=${p.centerY.toFixed(1)}`);
// S3: return inward from near wall
p = await hold(['Right'], 60);
harness.assert(p.centerX > -650, `S3 return inward: x=${p.centerX.toFixed(1)}`);
// S4: 4 corners not locking (push into corner, then escape)
const corners = [[-650,-650,'Left','Up'],[650,-650,'Right','Up'],[-650,650,'Left','Down'],[650,650,'Right','Down']];
for (const [cx,cy,kx,ky] of corners) {
  await tp(cx, cy);
  await hold([kx,ky], 90);
  const a = harness.getObjects('Player')[0];
  const ox = kx==='Left' ? 'Right' : 'Left';
  const oy = ky==='Up' ? 'Down' : 'Up';
  const b0 = harness.getObjects('Player')[0];
  for (const k of [ox,oy]) harness.setKeyPressed(k, true);
  await harness.stepFrames(45);
  for (const k of [ox,oy]) harness.setKeyPressed(k, false);
  const b = harness.getObjects('Player')[0];
  const moved = Math.hypot(b.centerX-b0.centerX, b.centerY-b0.centerY);
  harness.assert(moved > 30, `S4 corner (${cx},${cy}) escapes: moved ${moved.toFixed(1)}`);
  harness.assert(a.centerX > -760 && a.centerX < 800 && a.centerY > -760 && a.centerY < 800, `S4 corner (${cx},${cy}) inside bounds`);
}
// S5: diagonal into wall slides along it
await tp(-500, 350);
const s0 = harness.getObjects('Player')[0];
p = await hold(['Left','Up'], 120);
harness.assert(p.centerX > -720 && Math.abs(p.centerY - s0.centerY) > 40, `S5 wall slide: (${s0.centerX.toFixed(0)},${s0.centerY.toFixed(0)})->(${p.centerX.toFixed(0)},${p.centerY.toFixed(0)})`);
// S6: narrow passage through central gap (y -100 -> -300 via x -80..80 gap)
await tp(0, -100);
p = await hold(['Up'], 150);
harness.assert(p.centerY < -260, `S6 passage through: y=${p.centerY.toFixed(1)}`);
// S7: small room enter+exit (gap x -510..-450 at y=160)
await tp(-480, 250);
p = await hold(['Up'], 120);
harness.assert(p.centerY < 160, `S7 room enter: y=${p.centerY.toFixed(1)}`);
p = await hold(['Down'], 120);
harness.assert(p.centerY > 170, `S7 room exit: y=${p.centerY.toFixed(1)}`);
// S8: never fell
p = harness.getObjects('Player')[0];
