/* v1.0.0 — the 12-language shipping check, run through the game's own harness.
 *
 * It proves four things:
 *   1. the table holds every line in all twelve languages (nothing missing and
 *      no Japanese kana left inside a translation),
 *   2. the language can be switched from SETTINGS at any time and the HUD, the
 *      notification banner and the action labels follow it,
 *   3. switching back to Japanese gives the Japanese lines back (the events keep
 *      writing Japanese, so nothing is lost),
 *   4. the build reads `ICE WOLF v1.1.0` in every language.
 */
const num = (name) => harness.getSceneVariable(name)?.value ?? -1;
