harness.assert(num('WarpCount') === 1, `stepping on the smaller warp still teleports: ${num('WarpCount')}`);
const landed = harness.getObjects('Player')[0];
harness.assert(dist(landed, warps[1]) < 30, `the warp lands on its partner plate: ${round(dist(landed, warps[1]))}px`);
const speed = speeds[0];
harness.setObjectPosition(player.id, speed.centerX - 8.5, speed.centerY - 8.5);
await harness.stepFrames(3);
harness.assert(num('SpeedPadTriggers') >= 1, `the smaller speed floor still boosts: ${num('SpeedPadTriggers')}`);
harness.setSceneVariable('StairCooldownLeft', 0);
harness.setObjectVariable(player.id, 'State', 'Active');
harness.setObjectPosition(player.id, stairs[0].x + 6, stairs[0].y + 6);
await harness.stepFrames(4);
harness.assert(str('PlayerFloor') === '2F', `the smaller stair still carries the player up: ${str('PlayerFloor')}`);
harness.assert(num('StairRideCount') === 1, `one stair ride is counted: ${num('StairRideCount')}`);

/* 5. The hold reach is the smaller one: 70px works, 88px does not. */
harness.setSceneVariable('SwitchEscapeEnabled', true);
const entries = String(str('SwitchLayout')).split(';').filter(Boolean);
const liveIndex = entries.findIndex((entry) => {
  const parts = entry.split(':');
  return parts[3] === 'correct' && parts[4] === '0';
});
harness.assert(liveIndex >= 0, `a correct switch is still waiting: ${liveIndex}`);
const livePad = switches[liveIndex];
harness.setObjectPosition(player.id, livePad.centerX - 8.5, livePad.centerY - 78.5);
await harness.stepFrames(3);
harness.assert(num('SwitchHoldIndex') === liveIndex, `70px from the plate is inside the hold reach: ${num('SwitchHoldIndex')}`);
harness.setObjectPosition(player.id, livePad.centerX - 8.5, livePad.centerY - 96.5);
await harness.stepFrames(3);
harness.assert(num('SwitchHoldIndex') === -1, `88px from the plate is outside the hold reach: ${num('SwitchHoldIndex')}`);
harness.assert(harness.getSceneVariable('SwitchHoldVisible')?.value === false, 'no ring where there is no switch');

/* 6. A CPU still works a switch with the shorter approach distance. */
const worker = harness.getObjects('Actor')[0];
harness.setObjectVariable(worker.id, 'Role', 'Human');
harness.setObjectVariable(worker.id, 'State', 'Active');
harness.setObjectPosition(worker.id, livePad.centerX - 8.5, livePad.centerY - 8.5);
await harness.stepFrames(120);
harness.assert(num('SwitchTriggeredCount') >= 1, `a CPU holds the smaller switch at 28px: ${num('SwitchTriggeredCount')}`);
harness.assert(num('SwitchActiveCount') + num('SwitchDummyTriggered') + num('SwitchTrapTriggered') >= 1,
  `the CPU press counted somewhere: ${num('SwitchActiveCount')}/${num('SwitchDummyTriggered')}/${num('SwitchTrapTriggered')}`);

/* v1.1.0 — the Pro (in-app purchase) shipping check, run through the game's
 * own harness.
 *
 * It proves four things:
 *   1. without StoreKit (the browser / GDevelop preview) the screen still works
 *      and pressing purchase says "App Store version only" instead of throwing,
 *   2. with StoreKit present the price and the entitlement are read, and the
 *      purchase / cancel / pending / failure / restore answers land in the right
 *      state (locked stays locked, only a real purchase unlocks),
 *   3. a purchase unlocks Pro once and a second press never buys twice,
 *   4. every Pro line on the screen is in the chosen language, in all twelve.
 *
 * The fake StoreKit is the game's own (scene variable `ProTestAdapter`), so this
 * test needs no App Store account and no network.
 */
const num = (name) => harness.getSceneVariable(name)?.value ?? -1;
const str = (name) => harness.getSceneVariable(name)?.value ?? '';
const flag = (name) => harness.getSceneVariable(name)?.value === true;
const KANA = /[\u3040-\u30fa\u30fc-\u30ff]/;
const LANGS = ['ja', 'en', 'zh-Hans', 'zh-Hant', 'ko', 'es', 'fr', 'de', 'pt', 'it', 'hi', 'id'];
const i18n = () => runtimeScene.__iceWolfI18n;
const t = (key) => (i18n() && typeof i18n().t === 'function' ? i18n().t(key) : '');
const command = async (name) => {
  harness.setSceneVariable('ProCommand', name);
  await harness.stepFrames(2);
};
const setLanguage = async (code) => {
  harness.setSceneVariable('LanguageCommand', code);
  await harness.stepFrames(2);
};

await harness.goToScene('FROST LAB');
await harness.stepFrames(3);

// 0. the screen is there and the product is the one App Store Connect will hold
harness.assert(flag('ProUiReady'), 'the Pro screen is built');
harness.assert(str('ProProductId') === 'jp.signlink.IceWolf.pro', `the product id is the non-consumable jp.signlink.IceWolf.pro: ${str('ProProductId')}`);
harness.assert(str('ProStatus') === 'idle', `nothing is bought before the store is asked: ${str('ProStatus')}`);
harness.assert(flag('ProUnlocked') === false, 'the free version starts locked');

// 1. no StoreKit at all (browser preview): graceful, not broken
harness.setSceneVariable('ProTestAdapter', '');
await command('refresh');
harness.assert(flag('ProAvailable') === false, 'without StoreKit the store is reported unavailable');
harness.assert(str('ProStatus') === 'unavailable', `the status says so: ${str('ProStatus')}`);
harness.assert(str('ProMessage') === 'pro.storeUnavailable', `the screen explains where to buy: ${str('ProMessage')}`);
harness.assert(flag('ProUnlocked') === false, 'nothing is unlocked by a missing store');
await command('purchase');
harness.assert(str('ProStatus') === 'unavailable', 'pressing purchase without StoreKit does not throw and does not unlock');
harness.assert(flag('ProUnlocked') === false, 'still locked');
await command('restore');
harness.assert(str('ProStatus') === 'unavailable', 'pressing restore without StoreKit is safe too');

// 2. StoreKit present: the price and the entitlement are read
harness.setSceneVariable('ProTestAdapter', 'ok');
harness.setSceneVariable('ProTestPrice', '¥610');
await command('refresh');
harness.assert(flag('ProAvailable'), 'StoreKit is reachable');
harness.assert(str('ProPriceText') === '¥610', `the price comes from the store: ${str('ProPriceText')}`);
harness.assert(str('ProStatus') === 'ready', `the store answered: ${str('ProStatus')}`);
harness.assert(flag('ProUnlocked') === false, 'a free player is still free after a status read');
harness.assert(str('ProViewPrice').indexOf('¥610') >= 0, `the price line shows the store price: ${str('ProViewPrice')}`);

// 3. the answers that must NOT unlock
harness.setSceneVariable('ProTestAdapter', 'cancel');
await command('purchase');
harness.assert(str('ProStatus') === 'cancelled', `cancelling is reported: ${str('ProStatus')}`);
harness.assert(str('ProMessage') === 'pro.cancelled', `the screen says cancelled: ${str('ProMessage')}`);
harness.assert(flag('ProUnlocked') === false, 'cancelling does not unlock');
harness.setSceneVariable('ProTestAdapter', 'pending');
await command('purchase');
harness.assert(str('ProStatus') === 'pending', `a deferred purchase is reported: ${str('ProStatus')}`);
harness.assert(flag('ProUnlocked') === false, 'a pending purchase does not unlock yet');
harness.setSceneVariable('ProTestAdapter', 'fail');
await command('purchase');
harness.assert(str('ProStatus') === 'failed', `a failed purchase is reported: ${str('ProStatus')}`);
harness.assert(str('ProLastError') !== '', `the failure reason is kept: ${str('ProLastError')}`);
harness.assert(flag('ProUnlocked') === false, 'a failure does not unlock');
harness.setSceneVariable('ProTestAdapter', 'restoreNone');
await command('restore');
harness.assert(str('ProStatus') === 'nothing', `an empty restore is reported: ${str('ProStatus')}`);
harness.assert(str('ProMessage') === 'pro.nothingToRestore', `the screen says nothing was found: ${str('ProMessage')}`);
harness.assert(flag('ProUnlocked') === false, 'an empty restore does not unlock');

// 4. the purchase that does unlock, exactly once
harness.setSceneVariable('ProTestAdapter', 'ok');
await command('purchase');
harness.assert(flag('ProUnlocked'), 'a purchased result unlocks Pro');
harness.assert(str('ProStatus') === 'purchased', `the status is purchased: ${str('ProStatus')}`);
harness.assert(str('ProMessage') === 'pro.thanks', `the screen thanks the player: ${str('ProMessage')}`);
harness.assert(num('ProPurchaseCount') === 1, `one purchase was made: ${num('ProPurchaseCount')}`);
harness.assert(str('ProSource') === 'purchase', `the unlock came from a purchase: ${str('ProSource')}`);
harness.assert(str('ProTransactionId') === 'fake-transaction', `the transaction is remembered: ${str('ProTransactionId')}`);
harness.assert(str('ProViewBuy') === t('pro.owned'), `the buy button becomes owned: ${str('ProViewBuy')}`);
await command('purchase');
harness.assert(num('ProPurchaseCount') === 1, 'pressing purchase again while Pro is owned does not buy twice');

// 5. restore
harness.setSceneVariable('ProTestAdapter', 'restore');
await command('restore');
harness.assert(str('ProStatus') === 'restored', `a restore is reported: ${str('ProStatus')}`);
harness.assert(num('ProRestoreCount') === 1, `one restore was made: ${num('ProRestoreCount')}`);
harness.assert(str('ProSource') === 'restore', `the entitlement came from a restore: ${str('ProSource')}`);
harness.assert(flag('ProUnlocked'), 'Pro stays unlocked after a restore');

// 6. twelve languages on the Pro screen (Pro owned, restore message showing)
const keys = (i18n() && typeof i18n().keys === 'function' ? i18n().keys() : []).filter((key) => key.indexOf('pro.') === 0);
harness.assert(keys.length >= 28, `the Pro screen has its full set of lines: ${keys.length}`);
for (const key of keys) {
  const entry = i18n().ja(key);
  harness.assert(typeof entry === 'string' && entry.length > 0, `${key} has a Japanese line`);
}
const EXPECT = {
  ja: { badge: 'PRO', buy: '購入済み', restore: '購入を復元', close: 'とじる' },
  en: { badge: 'PRO', buy: 'Purchased', restore: 'Restore Purchases', close: 'Close' },
  ko: { badge: 'PRO', buy: '구매 완료', restore: '구매 복원', close: '닫기' },
  de: { badge: 'PRO', buy: 'Gekauft', restore: 'Käufe wiederherstellen', close: 'Schließen' }
};
for (const code of LANGS) {
  await setLanguage(code);
  harness.assert(str('ProViewBadge') === t('pro.unlocked'), `${code}: the badge reads the table: ${str('ProViewBadge')}`);
  harness.assert(str('ProViewStatus') === t('pro.statusPro'), `${code}: the status line reads the table: ${str('ProViewStatus')}`);
  harness.assert(str('ProViewRestore') === t('pro.restore'), `${code}: the restore label reads the table: ${str('ProViewRestore')}`);
  harness.assert(str('ProViewClose') === t('pro.close'), `${code}: the close label reads the table: ${str('ProViewClose')}`);
  harness.assert(str('ProViewMessage') === t('pro.restored'), `${code}: the message reads the table: ${str('ProViewMessage')}`);
  harness.assert(str('ProViewBuy').length > 0, `${code}: the buy label is filled`);
  if (code !== 'ja' && code !== 'zh-Hans' && code !== 'zh-Hant') {
    harness.assert(!KANA.test(str('ProViewStatus')), `${code}: the status is not Japanese: ${str('ProViewStatus')}`);
    harness.assert(!KANA.test(str('ProViewRestore')), `${code}: restore is not Japanese: ${str('ProViewRestore')}`);
  }
  if (EXPECT[code]) {
    harness.assert(str('ProViewBadge') === EXPECT[code].badge, `${code}: badge "${str('ProViewBadge')}"`);
    harness.assert(str('ProViewBuy') === EXPECT[code].buy, `${code}: buy "${str('ProViewBuy')}"`);
    harness.assert(str('ProViewRestore') === EXPECT[code].restore, `${code}: restore "${str('ProViewRestore')}"`);
    harness.assert(str('ProViewClose') === EXPECT[code].close, `${code}: close "${str('ProViewClose')}"`);
  }
}
await setLanguage('ja');
harness.assert(str('ProViewStatus') === 'プロ版が有効です。今後追加される内容がすべて使えます。', `Japanese comes back unharmed: ${str('ProViewStatus')}`);
await setLanguage('en');
